		'roi' => array( __( 'mining ROI', 'minemirth' ), array( __( 'payback', 'minemirth' ), __( 'ROI calculator', 'minemirth' ) ) ),
		'halving' => array( __( 'Bitcoin halving countdown', 'minemirth' ), array( __( 'halving impact', 'minemirth' ), __( 'block reward', 'minemirth' ) ) ),
		'difficulty' => array( __( 'difficulty adjustment', 'minemirth' ), array( __( 'mining difficulty', 'minemirth' ), __( 'estimate', 'minemirth' ) ) ),
		'hosting' => array( __( 'hosting vs home mining', 'minemirth' ), array( __( 'hosting cost', 'minemirth' ), __( 'home mining', 'minemirth' ) ) ),
		'power' => array( __( 'mining power calculator', 'minemirth' ), array( __( 'circuit planner', 'minemirth' ), __( 'amps', 'minemirth' ) ) ),
		'upgrade' => array( __( 'miner upgrade calculator', 'minemirth' ), array( __( 'upgrade', 'minemirth' ), __( 'older miners', 'minemirth' ) ) ),
		'solo' => array( __( 'solo mining odds', 'minemirth' ), array( __( 'solo mining calculator', 'minemirth' ), __( 'block', 'minemirth' ) ) ),
		'altcoin' => array( __( 'altcoin mining calculator', 'minemirth' ), array( __( 'Litecoin', 'minemirth' ), __( 'Kaspa', 'minemirth' ) ) ),
	);
	foreach ( mm_tools() as $id => $t ) {
		$pages[ 'tool-' . $id ] = array(
			't'      => $t['title'],
			'p'      => $hub . '/' . $t['slug'],
			'parent' => 'tools',
			'tpl'    => 'tool',
			'tool'   => $id,
			'icon'   => $t['icon'],
			'g'      => $groups[ $t['group'] ] ?? '',
			'x'      => $t['desc'],
			'st'     => $t['title'] . ' ' . __( '(Free, Live Data)', 'minemirth' ),
			'sd'     => $t['desc'],
			'kw'     => $tool_kw[ $id ][0] ?? '',
			'kw2'    => $tool_kw[ $id ][1] ?? array(),
			'o'      => ++$order,
		);
	}
	$pages['tools']['p'] = $hub;
	return $pages;
}

/** Planned path of a builder page. */
function mm_builder_path( string $key ): string {
	$pages = mm_builder_pages();
	return isset( $pages[ $key ] ) ? $pages[ $key ]['p'] : '';
}
